{
  "Comment": "PetPlantr order pipeline",
  "StartAt": "ValidateOrder",
  "States": {
    "ValidateOrder": {
      "Type": "Pass",
      "Comment": "Validate order data and user permissions",
      "Parameters": {
        "orderId.$": "$.orderId",
        "userId.$": "$.userId",
        "sku.$": "$.sku",
        "sizeTier.$": "$.sizeTier",
        "photoKeys.$": "$.photoKeys",
        "sessionId.$": "$.sessionId",
        "timestamp.$": "$.timestamp",
        "status": "VALIDATED",
        "validatedAt.$": "$$.State.EnteredTime"
      },
      "Next": "DownloadPhotos"
    },
    "DownloadPhotos": {
      "Type": "Task",
      "Comment": "Download user photos from S3 uploads bucket",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "${DownloadPhotosLambdaFunction}",
        "Payload": {
          "orderId.$": "$.orderId",
          "userId.$": "$.userId",
          "photoKeys.$": "$.photoKeys",
          "uploadBucket": "petplantr-uploads-dev"
        }
      },
      "Retry": [
        {
          "ErrorEquals": ["States.TaskFailed"],
          "IntervalSeconds": 2,
          "MaxAttempts": 3,
          "BackoffRate": 2.0
        }
      ],
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "Next": "HandleError"
        }
      ],
      "Next": "GenerateSTL"
    },
    "GenerateSTL": {
      "Type": "Task",
      "Comment": "Generate 3D STL mesh from photos using Shape-MVD",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "${GenerateSTLLambdaFunction}",
        "Payload": {
          "orderId.$": "$.orderId",
          "userId.$": "$.userId",
          "photoKeys.$": "$.photoKeys",
          "sizeTier.$": "$.sizeTier",
          "rawStlBucket": "petplantr-stl-raw-dev"
        }
      },
      "TimeoutSeconds": 300,
      "Retry": [
        {
          "ErrorEquals": ["States.TaskFailed"],
          "IntervalSeconds": 10,
          "MaxAttempts": 2,
          "BackoffRate": 2.0
        }
      ],
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "Next": "HandleError"
        }
      ],
      "Next": "ProcessSTL"
    },
    "ProcessSTL": {
      "Type": "Task",
      "Comment": "Clean and validate STL mesh for 3D printing",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "${ProcessSTLLambdaFunction}",
        "Payload": {
          "orderId.$": "$.orderId",
          "userId.$": "$.userId",
          "rawStlKey.$": "$.rawStlKey",
          "sizeTier.$": "$.sizeTier",
          "readyStlBucket": "petplantr-stl-ready-dev"
        }
      },
      "TimeoutSeconds": 180,
      "Retry": [
        {
          "ErrorEquals": ["States.TaskFailed"],
          "IntervalSeconds": 5,
          "MaxAttempts": 3,
          "BackoffRate": 1.5
        }
      ],
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "Next": "HandleError"
        }
      ],
      "Next": "NotifyCustomer"
    },
    "NotifyCustomer": {
      "Type": "Task",
      "Comment": "Send completion notification to customer",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "${NotifyCustomerLambdaFunction}",
        "Payload": {
          "orderId.$": "$.orderId",
          "userId.$": "$.userId",
          "readyStlKey.$": "$.readyStlKey",
          "status": "COMPLETED"
        }
      },
      "Retry": [
        {
          "ErrorEquals": ["States.TaskFailed"],
          "IntervalSeconds": 2,
          "MaxAttempts": 2
        }
      ],
      "End": true
    },
    "HandleError": {
      "Type": "Task",
      "Comment": "Handle processing errors and notify stakeholders",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "${HandleErrorLambdaFunction}",
        "Payload": {
          "orderId.$": "$.orderId",
          "userId.$": "$.userId",
          "error.$": "$.Error",
          "cause.$": "$.Cause",
          "status": "FAILED"
        }
      },
      "End": true
    }
  }
}

